import React from "react";
import { motion } from "framer-motion";
import { LightningBolt } from "lucide-react";

const Navbar = () => {
  return (
    <motion.nav
      initial={{ y: -40, opacity: 0 }}
      animate={{ y: 0, opacity: 1 }}
      transition={{ duration: 0.7, ease: "easeOut" }}
      className="fixed top-0 left-0 w-full bg-black backdrop-blur-md shadow-xl border-b border-gray-800 z-50"
    >
      <div className="max-w-7xl mx-auto px-8 py-4 flex items-center justify-start gap-3">
        {/* ✨ Cool Logo */}
        <motion.div
          className="flex items-center gap-2 cursor-pointer"
          whileHover={{ scale: 1.05 }}
          transition={{ type: "spring", stiffness: 200 }}
        >
          <LightningBolt className="w-8 h-8 text-white animate-pulse" />
          <motion.h1
            className="text-3xl md:text-4xl font-extrabold tracking-wide text-white select-none"
            style={{ fontFamily: "'Poppins', 'Inter', sans-serif" }}
            initial={{ opacity: 0, x: -20 }}
            animate={{ opacity: 1, x: 0 }}
            whileHover={{ textShadow: "0px 0px 12px rgba(255,255,255,0.8)" }}
            transition={{ duration: 0.5 }}
          >
            AI <span className="italic text-gray-300 font-semibold">Interview Coach</span>
          </motion.h1>
        </motion.div>
      </div>
    </motion.nav>
  );
};

export default Navbar;
